    dict: 성공시 - {
        "title": "암호화폐 공포&탐욕 지수",
        "timestamp": "2025-09-26T10:30:00Z",
        "current": {
            "value": 45,
            "classification": "공포",
            "description": "시장이 공포 상태입니다. 매수 기회일 수 있습니다."
        },
        "history": {
            "yesterday": {"value": 42, "classification": "공포"},
            "last_week": {"value": 38, "classification": "극도의 공포"},
            "last_month": {"value": 55, "classification": "중립"}
        },
        "trend_analysis": "지난 주 대비 상승세, 시장 심리 개선 중",
